-- Schema baseline, captured 2026-07-25 from the live database.
-- Generated by Postgres from its own catalogues; db pull needs Docker, which
-- is not installed. The leading underscore keeps db push from running it.

create extension if not exists "pg_stat_statements";

create extension if not exists "uuid-ossp";

create extension if not exists "pgcrypto";

create extension if not exists "supabase_vault";

create extension if not exists "pg_trgm";

create extension if not exists "pg_net";

create table if not exists public._deprecated_calls (
  id uuid not null default uuid_generate_v4(),
  caller_id text,
  receiver_id text,
  channel_id text,
  status text default 'ringing'::text,
  created_at timestamp without time zone default now(),
  accepted boolean default false,
  ended boolean default false,
