CREATE OR REPLACE FUNCTION public.accept_mentorship_request(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_req record;
  v_mentor_cap int;
  v_active int;
  v_conv_id uuid;
  v_mentorship_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated'; end if;

  select * into v_req from public.mentorship_requests
    where id = p_request_id and mentor_id = v_user and status = 'pending'
    for update;

  if v_req is null then raise exception 'Request not found or not yours'; end if;

  select max_active_mentees into v_mentor_cap
    from public.mentor_profiles where profile_id = v_user;
  if v_mentor_cap is null then raise exception 'Mentor profile missing'; end if;

  v_active := public.count_active_mentorships(v_user);
  if v_active >= v_mentor_cap then
    raise exception 'You are at capacity. End an existing mentorship to accept a new one.';
  end if;

  -- Create conversation (DM between mentor and mentee, flagged as mentorship)
  insert into public.conversations(is_group, created_by, user_1, user_2, is_mentorship)
  values (false, v_user, least(v_user::text, v_req.mentee_id::text)::uuid,
                                greatest(v_user::text, v_req.mentee_id::text)::uuid, true)
  returning id into v_conv_id;

  -- Create mentorship row
  insert into public.mentorships(
    mentor_id, mentee_id, institution_id, conversation_id, status
  ) values (
    v_user, v_req.mentee_id, v_req.institution_id, v_conv_id, 'active'
  ) returning id into v_mentorship_id;

  -- Back-reference on conversation
  update public.conversations
     set mentorship_id = v_mentorship_id
   where id = v_conv_id;

  -- Mark request accepted
  update public.mentorship_requests
     set status = 'accepted', responded_at = now()
   where id = p_request_id;

  return v_mentorship_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.accept_message_request(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_conv record;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into v_conv from public.conversations where id = p_conversation_id;
  if v_conv is null then
    raise exception 'conversation not found';
  end if;
  if v_conv.is_group then
    raise exception 'not a request';
  end if;
  if v_conv.request_status <> 'pending' then
    raise exception 'not a pending request';
  end if;

  -- Only the non-sender (the receiver) can accept.
  if v_conv.request_sender_id = v_user_id then
    raise exception 'sender cannot accept own request';
  end if;
  if v_conv.user_1 <> v_user_id and v_conv.user_2 <> v_user_id then
    raise exception 'not a party to this conversation';
  end if;

  update public.conversations
    set request_status = 'accepted',
        is_request = false
    where id = p_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.add_business_member(p_business_id uuid, p_username text, p_role text DEFAULT 'contributor'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_target uuid; v_name text;
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;
  if not is_business_owner(p_business_id) then
    raise exception 'Only an owner can add team members';
  end if;
  if p_role not in ('owner', 'manager', 'contributor') then
    raise exception 'Role must be owner, manager or contributor';
  end if;

  select id, full_name into v_target, v_name
  from profiles where lower(username) = lower(trim(p_username));
  if v_target is null then raise exception 'No account with that username'; end if;
  if v_target = p_business_id then raise exception 'A business cannot be its own member'; end if;

  insert into business_members (business_id, member_id, role)
  values (p_business_id, v_target, p_role)
  on conflict (business_id, member_id) do update set role = excluded.role;

  return jsonb_build_object('member_id', v_target, 'full_name', v_name, 'role', p_role);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_join_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_req record;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into v_req
  from public.affiliation_join_requests
  where id = p_request_id;

  if v_req is null then
    raise exception 'request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'request not pending';
  end if;

  if not public.is_affiliation_admin(v_req.affiliation_id) then
    raise exception 'not an admin of this affiliation';
  end if;

  insert into public.profile_affiliations (profile_id, affiliation_id, role, joined_at)
  values (v_req.user_id, v_req.affiliation_id, 'member', now())
  on conflict (profile_id, affiliation_id) do update
    set left_at = null, joined_at = now(), role = 'member';

  update public.affiliation_join_requests
    set status = 'approved', resolved_at = now(), resolved_by = v_user_id
    where id = p_request_id;

  update public.affiliations
    set member_count = (
      select count(*) from public.profile_affiliations
      where affiliation_id = v_req.affiliation_id and left_at is null
    )
    where id = v_req.affiliation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.autofill_institution_from_primary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_creator_id uuid;
  v_fallback_institution uuid;
BEGIN
  IF TG_TABLE_NAME = 'posts' THEN
    v_creator_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'jobs' THEN
    v_creator_id := NEW.posted_by;
  ELSIF TG_TABLE_NAME = 'events' THEN
    v_creator_id := NEW.created_by;
  ELSIF TG_TABLE_NAME = 'mingle_posts' THEN
    v_creator_id := NEW.host_id;
  ELSE
    RETURN NEW;
  END IF;

  IF NEW.institution_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Try primary first
  SELECT institution_id INTO v_fallback_institution
  FROM public.profile_institutions
  WHERE profile_id = v_creator_id AND is_primary = true
  LIMIT 1;

  -- Fallback: any institution the user belongs to, oldest first
  IF v_fallback_institution IS NULL THEN
    SELECT institution_id INTO v_fallback_institution
    FROM public.profile_institutions
    WHERE profile_id = v_creator_id
    ORDER BY created_at ASC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_fallback_institution IS NOT NULL THEN
    NEW.institution_id := v_fallback_institution;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.autofill_story_institution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_primary_institution uuid;
begin
  if NEW.institution_id is not null then
    return NEW;
  end if;

  select institution_id into v_primary_institution
  from public.profile_institutions
  where profile_id = NEW.user_id and is_primary = true
  limit 1;

  if v_primary_institution is not null then
    NEW.institution_id := v_primary_institution;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.broadcast_moment_notification(p_prompt_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_prompt campus_moment_prompts;
  v_count int;
BEGIN
  SELECT * INTO v_prompt FROM campus_moment_prompts WHERE id = p_prompt_id;
  IF v_prompt IS NULL THEN
    RAISE EXCEPTION 'Prompt not found';
  END IF;

  INSERT INTO notifications (recipient_id, actor_id, type, message, body_preview, data, account_type)
  SELECT
    pi.profile_id,
    v_prompt.created_by,
    'campus_moment',
    'Today''s Campus Moment is ready!',
    v_prompt.prompt_text,
    jsonb_build_object(
      'prompt_id', v_prompt.id,
      'prompt_text', v_prompt.prompt_text,
      'institution_id', v_prompt.institution_id,
      'window_start', v_prompt.window_start,
      'window_end', v_prompt.window_end,
      'is_daily_moment', true
    ),
    'personal'
  FROM profile_institutions pi
  WHERE pi.institution_id = v_prompt.institution_id
    AND NOT EXISTS (
      SELECT 1 FROM notifications n
      WHERE n.recipient_id = pi.profile_id
        AND n.type = 'campus_moment'
        AND (n.data->>'prompt_id')::text = v_prompt.id::text
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.bump_affiliation_member_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if TG_OP = 'INSERT' then
    update public.affiliations set member_count = member_count + 1 where id = NEW.affiliation_id;
  elsif TG_OP = 'DELETE' then
    update public.affiliations set member_count = greatest(member_count - 1, 0) where id = OLD.affiliation_id;
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.bump_story_views_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  update public.stories set views_count = views_count + 1 where id = NEW.story_id;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_act_as(p_target uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select auth.uid() is not null
     and (auth.uid() = p_target or is_business_member(p_target));
$function$
;

CREATE OR REPLACE FUNCTION public.can_view_story(p_story_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM stories s
    WHERE s.id = p_story_id
    AND (
      s.scope = 'global'
      OR s.user_id = auth.uid()
      OR s.institution_id IN (
        SELECT institution_id FROM profiles WHERE id = auth.uid()
      )
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.check_email_allowed(p_email text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_domain TEXT;
  v_blocked BOOLEAN;
  v_is_school BOOLEAN;
BEGIN
  v_domain := lower(split_part(p_email, '@', 2));
  v_blocked := public.is_email_blocked(p_email);
  v_is_school := public.is_verified_school_domain(p_email);

  RETURN json_build_object(
    'allowed', NOT v_blocked,
    'domain', v_domain,
    'is_school_domain', v_is_school,
    'reason', CASE WHEN v_blocked THEN 'disposable_email_not_allowed' ELSE null END
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_institution(p_institution_id uuid, p_relationship_type text DEFAULT 'current'::text, p_start_year integer DEFAULT NULL::integer, p_end_year integer DEFAULT NULL::integer, p_make_primary boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_user_email text;
  v_auto_verified boolean := false;
  v_existing_primary_count int;
  v_should_be_primary boolean;
  v_pi_id uuid;
  v_matched_institution uuid;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  -- Validate relationship_type against the check constraint.
  if p_relationship_type not in ('current','alumni','past','prospective','faculty','staff') then
    raise exception 'invalid relationship_type: %', p_relationship_type;
  end if;

  -- Validate the institution exists and is active.
  if not exists (select 1 from public.institutions where id = p_institution_id and is_active = true) then
    raise exception 'institution not found or inactive';
  end if;

  -- Pull user's email for domain matching.
  select email into v_user_email from auth.users where id = v_user_id;

  -- If caller's email domain matches this institution's registered
  -- domain, auto-verify. Works for exact match and subdomains.
  if v_user_email is not null then
    select institution_id into v_matched_institution
    from public.match_email_to_institution(v_user_email);

    if v_matched_institution = p_institution_id then
      v_auto_verified := true;
    end if;
  end if;

  -- Decide whether this should be marked primary. Caller can force
  -- it, OR if this is their first institution, it becomes primary.
  select count(*) into v_existing_primary_count
  from public.profile_institutions
  where profile_id = v_user_id;

  v_should_be_primary := p_make_primary or v_existing_primary_count = 0;

  -- If we're making this primary, clear any existing primary.
  if v_should_be_primary then
    update public.profile_institutions
      set is_primary = false
      where profile_id = v_user_id and is_primary = true;
  end if;

  -- Upsert the membership.
  insert into public.profile_institutions
    (profile_id, institution_id, relationship_type, start_year, end_year,
     is_primary, verified_via_email, verified_at)
  values
    (v_user_id, p_institution_id, p_relationship_type, p_start_year, p_end_year,
     v_should_be_primary, v_auto_verified, case when v_auto_verified then now() else null end)
  on conflict (profile_id, institution_id) do update set
    relationship_type  = excluded.relationship_type,
    start_year         = excluded.start_year,
    end_year           = excluded.end_year,
    is_primary         = excluded.is_primary,
    verified_via_email = profile_institutions.verified_via_email or excluded.verified_via_email,
    verified_at        = coalesce(profile_institutions.verified_at, excluded.verified_at)
  returning id into v_pi_id;

  return v_pi_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_stories()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted int;
begin
  delete from public.stories where expires_at < (now() - interval '7 days');
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;

  insert into conversation_settings (conversation_id, user_id, cleared_at)
  values (p_conversation_id, auth.uid(), now())
  on conflict (conversation_id, user_id) do update set cleared_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.count_active_mentorships(p_mentor_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int
  from public.mentorships
  where mentor_id = p_mentor_id and status = 'active';
$function$
;

CREATE OR REPLACE FUNCTION public.create_affiliation_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conv_id uuid;
begin
  if NEW.conversation_id is not null then
    return NEW;
  end if;

  insert into public.conversations (
    is_group, group_name, created_by, user_1,
    affiliation_id,
    last_message, last_message_time, last_message_sender_id,
    admin_only_edit, admin_only_invite
  )
  values (
    true, NEW.name, NEW.created_by, NEW.created_by,
    NEW.id,
    'Community created', now(), NEW.created_by,
    false, false
  )
  returning id into v_conv_id;

  update public.affiliations
    set conversation_id = v_conv_id
    where id = NEW.id;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_group_conversation(p_group_name text, p_member_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid := auth.uid();
  v_conv_id uuid;
  v_member_id uuid;
begin
  if v_creator_id is null then
    raise exception 'unauthorized';
  end if;
  if p_group_name is null or length(trim(p_group_name)) = 0 then
    raise exception 'group name required';
  end if;
  if p_member_ids is null or array_length(p_member_ids, 1) < 1 then
    raise exception 'at least one member required';
  end if;

  insert into public.conversations (
    is_group, group_name, created_by, user_1,
    last_message, last_message_time, last_message_sender_id,
    admin_only_edit, admin_only_invite
  )
  values (
    true, trim(p_group_name), v_creator_id, v_creator_id,
    'Group created', now(), v_creator_id,
    false, false
  )
  returning id into v_conv_id;

  insert into public.conversation_members (conversation_id, user_id, role, joined_at)
  values (v_conv_id, v_creator_id, 'admin', now());

  foreach v_member_id in array p_member_ids loop
    if v_member_id <> v_creator_id then
      insert into public.conversation_members (conversation_id, user_id, role, joined_at)
      values (v_conv_id, v_member_id, 'member', now())
      on conflict do nothing;
    end if;
  end loop;

  return v_conv_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_meeting(p_title text, p_is_public boolean DEFAULT true, p_duration_hours integer DEFAULT 24)
 RETURNS meetings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_inst uuid;
  v_room_name text;
  v_row public.meetings;
begin
  if v_user is null then raise exception 'Not authenticated'; end if;
  if p_duration_hours < 1 or p_duration_hours > 48 then
    raise exception 'Duration must be 1-48 hours';
  end if;

  v_inst := public.get_user_primary_institution(v_user);
  v_room_name := public.gen_meeting_room_name();

  insert into public.meetings(
    room_name, title, host_id, institution_id, is_public, expires_at
  ) values (
    v_room_name,
    trim(p_title),
    v_user,
    v_inst,
    p_is_public,
    now() + (p_duration_hours || ' hours')::interval
  ) returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.decline_join_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_req record;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into v_req
  from public.affiliation_join_requests where id = p_request_id;

  if v_req is null then
    raise exception 'request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'request not pending';
  end if;
  if not public.is_affiliation_admin(v_req.affiliation_id) then
    raise exception 'not an admin of this affiliation';
  end if;

  update public.affiliation_join_requests
    set status = 'declined', resolved_at = now(), resolved_by = v_user_id
    where id = p_request_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.decline_mentorship_request(p_request_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;

  update public.mentorship_requests
     set status = 'declined', responded_at = now(), response_note = p_note
   where id = p_request_id and mentor_id = auth.uid() and status = 'pending';

  if not found then raise exception 'Request not found or not yours'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.decline_message_request(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_conv record;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into v_conv from public.conversations where id = p_conversation_id;
  if v_conv is null then
    raise exception 'conversation not found';
  end if;
  if v_conv.is_group then
    raise exception 'not a request';
  end if;
  if v_conv.request_status <> 'pending' then
    raise exception 'not a pending request';
  end if;
  if v_conv.user_1 <> v_user_id and v_conv.user_2 <> v_user_id then
    raise exception 'not a party to this conversation';
  end if;
  if v_conv.request_sender_id = v_user_id then
    raise exception 'sender cannot decline own request';
  end if;

  -- Delete messages first (no cascade defined), then the conversation.
  delete from public.messages where conversation_id = p_conversation_id;
  delete from public.conversations where id = p_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_business_review(p_business_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_bp uuid;
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;
  select id into v_bp from business_profiles where profile_id = p_business_id;
  if v_bp is null then return; end if;
  delete from business_reviews where business_id = v_bp and user_id = auth.uid();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_message_for_everyone(p_message_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_sender uuid; v_created timestamptz;
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;

  select sender_id, created_at into v_sender, v_created
  from messages where id = p_message_id;
  if v_sender is null then raise exception 'Message not found'; end if;
  if v_sender <> auth.uid() then raise exception 'You can only delete your own messages for everyone'; end if;
  if v_created < now() - interval '48 hours' then
    raise exception 'This message is too old to delete for everyone';
  end if;

  update messages
     set deleted_at = now(),
         deleted_by = auth.uid(),
         text = null,
         media_url = null,
         media_type = null
   where id = p_message_id;
end;
$function$
;

