CREATE OR REPLACE FUNCTION public.get_pending_join_requests(p_affiliation_id uuid)
 RETURNS TABLE(request_id uuid, user_id uuid, full_name text, username text, avatar_url text, institution_name text, message text, requested_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    ajr.id as request_id,
    ajr.user_id,
    p.full_name,
    p.username,
    p.avatar_url,
    (
      select i.name from public.profile_institutions pi
      join public.institutions i on i.id = pi.institution_id
      where pi.profile_id = ajr.user_id and pi.is_primary = true
      limit 1
    ) as institution_name,
