CREATE OR REPLACE FUNCTION public.post_campus_moment(p_prompt_id uuid, p_story_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_prompt campus_moment_prompts;
  v_story stories;
  v_is_late boolean;
  v_late_seconds int;
  v_existing campus_moment_posts;
  v_result campus_moment_posts;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_prompt FROM campus_moment_prompts WHERE id = p_prompt_id;
  IF v_prompt IS NULL THEN
    RAISE EXCEPTION 'Prompt not found';
  END IF;

  SELECT * INTO v_story FROM stories WHERE id = p_story_id;
  IF v_story IS NULL THEN
    RAISE EXCEPTION 'Story not found';
  END IF;

  IF v_story.user_id != auth.uid() THEN
    RAISE EXCEPTION 'Story does not belong to you';
  END IF;

  -- Check for existing post (handle duplicate gracefully)
  SELECT * INTO v_existing FROM campus_moment_posts
    WHERE prompt_id = p_prompt_id AND user_id = auth.uid();
  IF v_existing IS NOT NULL THEN
    RETURN row_to_json(v_existing);
  END IF;

  v_is_late := now() > v_prompt.window_end;
  v_late_seconds := CASE WHEN v_is_late
    THEN EXTRACT(EPOCH FROM (now() - v_prompt.window_end))::int
    ELSE 0
  END;

  INSERT INTO campus_moment_posts (prompt_id, story_id, user_id, is_late, late_seconds)
  VALUES (p_prompt_id, p_story_id, auth.uid(), v_is_late, v_late_seconds)
  RETURNING * INTO v_result;

  RETURN row_to_json(v_result);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.post_payment_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Only on the transition into completed, and only once.
  if new.status <> 'completed' or old.status is not distinct from 'completed' then
    return new;
  end if;
  if exists (select 1 from messages where payment_id = new.id) then
    return new;
  end if;

  insert into messages (conversation_id, sender_id, receiver_id, text, media_type, payment_id)
  values (new.conversation_id, new.sender_id, new.recipient_id, null, 'payment', new.id);

  update conversations
     set last_message = 'Payment',
         last_message_time = now(),
         last_message_sender_id = new.sender_id
   where id = new.conversation_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.record_call_event(p_call_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id       uuid;
  v_receiver_id     uuid;
  v_conversation_id uuid;
  v_is_video        boolean;
  v_status          text;
  v_duration_sec    integer;
  v_call_type       text;
  v_type_label      text;
  v_msg_text        text;
  v_meta_json       text;
  v_existing_id     uuid;
  v_dur_h           integer;
  v_dur_m           integer;
  v_dur_s           integer;
  v_dur_str         text;
BEGIN
  -- 1. Read call_sessions
  SELECT
    cs.initiator_id,
    cs.receiver_id,
    cs.conversation_id,
    COALESCE(cs.is_video, false),
    cs.status,
    COALESCE(cs.duration_sec, 0)
  INTO
    v_caller_id,
    v_receiver_id,
    v_conversation_id,
    v_is_video,
    v_status,
    v_duration_sec
  FROM call_sessions cs
  WHERE cs.id = p_call_id;

  -- If call not found, exit
  IF v_caller_id IS NULL THEN
    RETURN;
  END IF;

  -- Only process terminal states
  IF v_status NOT IN ('ended', 'missed', 'declined') THEN
    RETURN;
  END IF;

  -- 2. Resolve conversation
  -- First try the conversation_id stored on call_sessions
  IF v_conversation_id IS NULL AND v_caller_id IS NOT NULL AND v_receiver_id IS NOT NULL THEN
    -- Find direct conversation between caller and receiver
    SELECT c.id INTO v_conversation_id
    FROM conversations c
    WHERE c.type = 'direct'
      AND (
        (c.user_1 = LEAST(v_caller_id, v_receiver_id) AND c.user_2 = GREATEST(v_caller_id, v_receiver_id))
        OR
        (c.user_1 = GREATEST(v_caller_id, v_receiver_id) AND c.user_2 = LEAST(v_caller_id, v_receiver_id))
      )
    LIMIT 1;
  END IF;

  -- If still no conversation, cannot insert message
  IF v_conversation_id IS NULL THEN
    RETURN;
  END IF;

  -- 3. Check for duplicate: if a call_event for this call_id already exists, exit
  SELECT m.id INTO v_existing_id
  FROM messages m
  WHERE m.conversation_id = v_conversation_id
    AND m.media_type = 'call_event'
    AND m.media_url LIKE '%' || p_call_id::text || '%'
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN;
  END IF;

  -- 4. Build message text
  IF v_is_video THEN
    v_call_type := 'video';
    v_type_label := 'Video';
  ELSE
    v_call_type := 'voice';
    v_type_label := 'Voice';
  END IF;

  IF v_status = 'missed' THEN
    v_msg_text := 'Missed ' || v_call_type || ' call';
  ELSIF v_status = 'declined' THEN
    v_msg_text := 'Declined ' || v_call_type || ' call';
  ELSIF v_status = 'ended' AND v_duration_sec > 0 THEN
    -- Format duration as MM:SS or H:MM:SS
    v_dur_h := v_duration_sec / 3600;
    v_dur_m := (v_duration_sec % 3600) / 60;
    v_dur_s := v_duration_sec % 60;
    IF v_dur_h > 0 THEN
      v_dur_str := v_dur_h::text || ':' || LPAD(v_dur_m::text, 2, '0') || ':' || LPAD(v_dur_s::text, 2, '0');
    ELSE
      v_dur_str := LPAD(v_dur_m::text, 2, '0') || ':' || LPAD(v_dur_s::text, 2, '0');
    END IF;
    v_msg_text := v_type_label || ' call · ' || v_dur_str;
  ELSE
    v_msg_text := v_type_label || ' call';
  END IF;

  -- 5. Build JSON metadata
  v_meta_json := jsonb_build_object(
    'call_id', p_call_id::text,
    'call_type', v_call_type,
    'status', v_status,
    'duration_secs', v_duration_sec
  )::text;

  -- 6. Insert message
  INSERT INTO messages (
    conversation_id,
    sender_id,
    receiver_id,
    text,
    media_type,
    media_url,
    is_system_message
  ) VALUES (
    v_conversation_id,
    v_caller_id,
    v_receiver_id,
    v_msg_text,
    'call_event',
    v_meta_json,
    true
  );

  -- 7. Update conversation preview
  UPDATE conversations
  SET last_message = CASE WHEN v_is_video THEN '📹 ' ELSE '📞 ' END || v_msg_text,
      last_message_time = now()
  WHERE id = v_conversation_id;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_meeting_join(p_meeting_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_part_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated'; end if;

  insert into public.meeting_participants(meeting_id, user_id, joined_at)
  values (p_meeting_id, v_user, now())
  returning id into v_part_id;

  return v_part_id;
end;
$function$
;

