    select account_type into new.account_type
    from public.profiles where id = new.user_id;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_dm(p_receiver_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_conv_id uuid;
  v_same_school boolean;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;
  if p_receiver_id = v_user_id then
    raise exception 'cannot message yourself';
  end if;
  if not exists (select 1 from public.profiles where id = p_receiver_id) then
    raise exception 'receiver not found';
  end if;

  -- Look for an existing DM between these two users (order-independent).
  select c.id into v_conv_id
  from public.conversations c
  where c.is_group = false
    and (
      (c.user_1 = v_user_id and c.user_2 = p_receiver_id)
      or (c.user_1 = p_receiver_id and c.user_2 = v_user_id)
    )
  limit 1;

  if v_conv_id is not null then
    return v_conv_id;
  end if;

  v_same_school := public.users_share_institution(v_user_id, p_receiver_id);

  insert into public.conversations (
    user_1, user_2, is_group, created_by,
    is_request, request_status, request_sender_id, requested_at,
    admin_only_edit, admin_only_invite
  )
  values (
    v_user_id, p_receiver_id, false, v_user_id,
    not v_same_school,
    case when v_same_school then 'none' else 'pending' end,
    case when v_same_school then null else v_user_id end,
    case when v_same_school then null else now() end,
    false, false
  )
  returning id into v_conv_id;

  return v_conv_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_dm_ctx(p_receiver_id uuid, p_context text DEFAULT 'personal'::text, p_ref_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; a uuid; b uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_receiver_id = auth.uid() then raise exception 'cannot message yourself'; end if;
  a := least(auth.uid(), p_receiver_id);
  b := greatest(auth.uid(), p_receiver_id);

  select id into v_id from public.conversations
   where type = 'direct' and coalesce(is_group,false) = false
     and ((user_1 = a and user_2 = b) or (user_1 = b and user_2 = a))
     and coalesce(context,'personal') = p_context
     and coalesce(context_ref_id::text,'') = coalesce(p_ref_id::text,'')
   limit 1;
  if v_id is not null then return v_id; end if;

  insert into public.conversations (user_1, user_2, type, is_group, context, context_ref_id, last_message, last_message_time)
  values (a, b, 'direct', false, p_context, p_ref_id, '', now())
  returning id into v_id;
  return v_id;
end $function$
;

