CREATE OR REPLACE FUNCTION public.upsert_mentor_profile(p_bio text, p_expertise_tags text[], p_help_with text[], p_availability_note text, p_max_active_mentees integer, p_mentor_kind text, p_is_active boolean)
 RETURNS mentor_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_inst uuid;
  v_row public.mentor_profiles;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;

  v_inst := public.get_user_primary_institution(v_user);
  if v_inst is null then
    raise exception 'You must be affiliated with an institution to become a mentor';
  end if;

  if p_max_active_mentees < 1 or p_max_active_mentees > 5 then
    raise exception 'Capacity must be between 1 and 5';
  end if;

  if p_mentor_kind not in ('student_mentor','alumni','faculty','staff') then
    raise exception 'Invalid mentor kind';
  end if;

  insert into public.mentor_profiles(
    profile_id, institution_id, is_active, bio, expertise_tags,
    help_with, availability_note, max_active_mentees, mentor_kind
  ) values (
    v_user, v_inst, p_is_active, p_bio, coalesce(p_expertise_tags, '{}'),
    coalesce(p_help_with, '{}'), p_availability_note, p_max_active_mentees, p_mentor_kind
  )
  on conflict (profile_id) do update set
    institution_id = excluded.institution_id,
    is_active = excluded.is_active,
    bio = excluded.bio,
    expertise_tags = excluded.expertise_tags,
    help_with = excluded.help_with,
    availability_note = excluded.availability_note,
    max_active_mentees = excluded.max_active_mentees,
    mentor_kind = excluded.mentor_kind,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.users_share_institution(p_user_a uuid, p_user_b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.profile_institutions pa
    join public.profile_institutions pb on pa.institution_id = pb.institution_id
    where pa.profile_id = p_user_a and pb.profile_id = p_user_b
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_event(p_event_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.events e
    where e.id = p_event_id
      and (
        e.created_by = auth.uid()
        or e.scope = 'global'
        or (e.scope = 'institution' and public.viewer_can_see_institution(e.institution_id))
        or (e.scope = 'affiliation' and exists (
          select 1 from public.profile_affiliations pa
          where pa.profile_id = auth.uid()
            and pa.affiliation_id = e.affiliation_id
            and pa.left_at is null
        ))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_institution(p_institution_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p_institution_id is null
    or auth.uid() is null  -- service-role and unauthenticated edge cases, handled elsewhere
    or exists (
      select 1 from public.profile_institutions pi
      where pi.profile_id = auth.uid()
        and pi.institution_id = p_institution_id
    );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_job(p_job_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.jobs j
    where j.id = p_job_id
      and (
        j.posted_by = auth.uid()
        or j.scope = 'global'
        or (j.scope = 'institution' and public.viewer_can_see_institution(j.institution_id))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_mingle(p_mingle_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.mingle_posts mp
    where mp.id = p_mingle_id
      and (
        mp.host_id = auth.uid()
        or mp.scope = 'global'
        or (mp.scope = 'institution' and public.viewer_can_see_institution(mp.institution_id))
        or (mp.scope = 'affiliation' and exists (
          select 1 from public.profile_affiliations pa
          where pa.profile_id = auth.uid()
            and pa.affiliation_id = mp.affiliation_id
            and pa.left_at is null
        ))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_post(p_post_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.posts p
    where p.id = p_post_id
      and (
        p.user_id = auth.uid()
        or p.scope = 'global'
        or (p.scope = 'institution' and public.viewer_can_see_institution(p.institution_id))
        or (p.scope = 'affiliation' and exists (
          select 1 from public.profile_affiliations pa
          where pa.profile_id = auth.uid()
            and pa.affiliation_id = p.affiliation_id
            and pa.left_at is null
        ))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_profile(p_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    auth.uid() = p_profile_id
    or exists (
      select 1 from public.profiles pr
      where pr.id = p_profile_id
        and coalesce(pr.profile_visibility, 'public') = 'public'
    )
    or public.viewer_shares_institution_with(p_profile_id);
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_can_see_story(p_story_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.stories s
    where s.id = p_story_id
      and s.expires_at > now()
      and (
        s.user_id = auth.uid()
        or (
          auth.uid() is not null
          and (
            s.scope = 'global'
            or (s.scope = 'institution' and public.viewer_can_see_institution(s.institution_id))
            or (s.scope = 'affiliation' and exists (
              select 1 from public.profile_affiliations pa
              where pa.profile_id = auth.uid() and pa.affiliation_id = s.affiliation_id and pa.left_at is null))
          )
          and (
            coalesce(s.audience, 'everyone') = 'everyone'
            or (s.audience = 'followers' and exists (
              select 1 from public.follows f
              where f.following_id = s.user_id and f.follower_id = auth.uid()))
            or (s.audience = 'close_friends' and exists (
              select 1 from public.close_friends cf
              where cf.owner_id = s.user_id and cf.friend_id = auth.uid()))
            or (s.audience = 'only_with' and exists (
              select 1 from public.story_shared_with sw
              where sw.story_id = s.id and sw.user_id = auth.uid()))
            or (s.audience = 'except' and not exists (
              select 1 from public.story_hidden_from hf
              where hf.story_id = s.id and hf.user_id = auth.uid()))
          )
        )
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.viewer_shares_institution_with(p_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.profile_institutions a
    join public.profile_institutions b on a.institution_id = b.institution_id
    where a.profile_id = auth.uid()
      and b.profile_id = p_profile_id
  );
$function$
;

CREATE OR REPLACE FUNCTION public.vote_story_poll(p_poll_id uuid, p_option_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_option_poll_id uuid;
  v_story_id uuid;
BEGIN
  -- Verify option belongs to this poll
  SELECT poll_id INTO v_option_poll_id
  FROM story_poll_options
  WHERE id = p_option_id;

  IF v_option_poll_id IS NULL THEN
    RAISE EXCEPTION 'Option not found';
  END IF;

  IF v_option_poll_id != p_poll_id THEN
    RAISE EXCEPTION 'Option does not belong to this poll';
  END IF;

  -- Upsert vote
  INSERT INTO story_poll_votes (poll_id, option_id, user_id)
  VALUES (p_poll_id, p_option_id, auth.uid())
  ON CONFLICT (poll_id, user_id)
  DO UPDATE SET option_id = EXCLUDED.option_id, updated_at = now();

  -- Get story_id to return updated results
  SELECT story_id INTO v_story_id
  FROM story_polls WHERE id = p_poll_id;

  -- Return fresh results
  RETURN get_story_poll(v_story_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.withdraw_mentorship_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.mentorship_requests
     set status = 'withdrawn', responded_at = now()
   where id = p_request_id and mentee_id = auth.uid() and status = 'pending';

  if not found then raise exception 'Request not found or not yours'; end if;
end;
$function$
;

