create policy "Callers insert calls" on public._deprecated_calls as PERMISSIVE for INSERT to public with check (((auth.uid())::text = caller_id));

create policy "Involved users read calls" on public._deprecated_calls as PERMISSIVE for SELECT to public using ((((auth.uid())::text = caller_id) OR ((auth.uid())::text = receiver_id)));

create policy "Involved users update calls" on public._deprecated_calls as PERMISSIVE for UPDATE to public using ((((auth.uid())::text = caller_id) OR ((auth.uid())::text = receiver_id)));

create policy calls_insert on public._deprecated_calls as PERMISSIVE for INSERT to public with check (((auth.uid())::text = caller_id));

create policy calls_select on public._deprecated_calls as PERMISSIVE for SELECT to public using ((((auth.uid())::text = caller_id) OR ((auth.uid())::text = receiver_id)));

create policy calls_update on public._deprecated_calls as PERMISSIVE for UPDATE to public using ((((auth.uid())::text = caller_id) OR ((auth.uid())::text = receiver_id)));

