create policy ajr_insert_own on public.affiliation_join_requests as PERMISSIVE for INSERT to public with check ((user_id = auth.uid()));

create policy ajr_select_own on public.affiliation_join_requests as PERMISSIVE for SELECT to public using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profile_affiliations pa
  WHERE ((pa.affiliation_id = affiliation_join_requests.affiliation_id) AND (pa.profile_id = auth.uid()) AND (pa.role = ANY (ARRAY['admin'::text, 'officer'::text, 'founder'::text])) AND (pa.left_at IS NULL))))));

create policy ajr_update_admin on public.affiliation_join_requests as PERMISSIVE for UPDATE to public using ((EXISTS ( SELECT 1
   FROM profile_affiliations pa
  WHERE ((pa.affiliation_id = affiliation_join_requests.affiliation_id) AND (pa.profile_id = auth.uid()) AND (pa.role = ANY (ARRAY['admin'::text, 'officer'::text, 'founder'::text])) AND (pa.left_at IS NULL)))));

create policy affiliations_delete_admin on public.affiliations as PERMISSIVE for DELETE to public using ((EXISTS ( SELECT 1
   FROM profile_affiliations pa
  WHERE ((pa.affiliation_id = affiliations.id) AND (pa.profile_id = auth.uid()) AND (pa.role = 'founder'::text) AND (pa.left_at IS NULL)))));

create policy affiliations_insert on public.affiliations as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = created_by));

create policy affiliations_select on public.affiliations as PERMISSIVE for SELECT to public using (true);

create policy affiliations_update_admin on public.affiliations as PERMISSIVE for UPDATE to public using (is_affiliation_admin(id)) with check (is_affiliation_admin(id));

create policy blocked_users_all on public.blocked_users as PERMISSIVE for ALL to public using (((auth.uid())::text = (blocker_id)::text)) with check (((auth.uid())::text = (blocker_id)::text));

create policy blocked_users_delete_own on public.blocked_users as PERMISSIVE for DELETE to public using ((auth.uid() = blocker_id));

create policy blocked_users_insert_own on public.blocked_users as PERMISSIVE for INSERT to public with check ((auth.uid() = blocker_id));

create policy blocked_users_select_own on public.blocked_users as PERMISSIVE for SELECT to public using ((auth.uid() = blocker_id));

