create policy "Users can view call participants" on public.call_participants as PERMISSIVE for SELECT to public using (((user_id = auth.uid()) OR (call_session_id IN ( SELECT call_sessions.id
   FROM call_sessions
  WHERE (call_sessions.initiator_id = auth.uid()))) OR (call_session_id IN ( SELECT call_participants_1.call_session_id
   FROM call_participants call_participants_1
  WHERE (call_participants_1.user_id = auth.uid())))));

create policy call_sessions_insert_initiator on public.call_sessions as PERMISSIVE for INSERT to authenticated with check ((initiator_id = auth.uid()));

create policy call_sessions_no_delete on public.call_sessions as PERMISSIVE for DELETE to authenticated using (false);

create policy call_sessions_select_participants on public.call_sessions as PERMISSIVE for SELECT to authenticated using (((initiator_id = auth.uid()) OR (receiver_id = auth.uid()) OR (EXISTS ( SELECT 1
